def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    rows = [r for r in range(h)
            if len(set(grid[r])) == 1 and grid[r][0] != background]
    cols = [c for c in range(w)
            if len({grid[r][c] for r in range(h)}) == 1
            and grid[0][c] != background]

    rb = [-1] + rows + [h]
    cb = [-1] + cols + [w]
    tiles = [(rb[i] + 1, rb[i + 1], cb[j] + 1, cb[j + 1])
             for i in range(len(rb) - 1)
             for j in range(len(cb) - 1)]

    pattern = {}
    for r0, r1, c0, c1 in tiles:
        for r in range(r0, r1):
            for c in range(c0, c1):
                color = grid[r][c]
                if color != background:
                    key = (r - r0, c - c0)
                    pattern[key] = color

    out = [row[:] for row in grid]
    for r0, r1, c0, c1 in tiles:
        for (dr, dc), color in pattern.items():
            if r0 + dr < r1 and c0 + dc < c1:
                out[r0 + dr][c0 + dc] = color
    return out
